#include <string>
#include <stack>
using namespace std;

class Solution {
public:
    string reverseParentheses(string s) {
        stack<string> stk;
        string curr = "";
        for (char c : s) {
            if (c == '(') {
                stk.push(curr);
                curr = "";
            } else if (c == ')') {
                reverse(curr.begin(), curr.end());
                curr = stk.top() + curr;
                stk.pop();
            } else {
                curr += c;
            }
        }
        return curr;
    }
};
